from pathlib import Path
import h5py
files = sorted([p for p in Path('data').rglob('*') if p.is_file()])
for p in files:
    print(f'===== {p} =====')
    suf = p.suffix.lower()
    if suf in {'.nwb', '.h5', '.hdf5'}:
        try:
            with h5py.File(p, 'r') as f:
                print('top_level_keys:', list(f.keys())[:30])
                for key in ['general', 'units', 'intervals', 'processing', 'acquisition']:
                    if key in f:
                        print(key, 'subkeys:', list(f[key].keys())[:30] if hasattr(f[key], 'keys') else 'dataset')
        except Exception as e:
            print('HDF5 read failed:', e)
    else:
        print('non-HDF5 file')
