import shutil, subprocess
for pdf in ['datapaper.pdf', 'methodpaper.pdf', 'ChenLiuEtAl2023_SpikeSortingQC.pdf']:
    print('===== ', pdf, ' =====')
    if shutil.which('pdftotext'):
        out = subprocess.check_output(['pdftotext', pdf, '-'], text=True, errors='ignore')
        keys = ['subject', 'session', 'trial', 'neuron', 'unit', 'go cue', 'go_start', 'sample', 'delay', 'photostim', 'early lick', 'outcome', 'hit', 'miss', 'ignore', 'tongue', 'bin', '50 ms', '0.05', 'quality', 'presence ratio', 'isi violation']
        lines = out.splitlines()
        for i, line in enumerate(lines):
            low = line.lower()
            if any(k in low for k in keys):
                print(f'{i+1}: {line[:300]}')
    else:
        print('pdftotext not available')
